style.css:
@-moz-document regexp(".*") {
body {
        font-family: 'Play', sans-serif !important;
        background-color: black !important;
        background-attachment: fixed !important;
        background-size: cover !important;
        margin: 0 !important;
        overflow-x: hidden !important;
    }

    body::before, body::after {
        content: "" !important;
        position: fixed !important;
        top: 0 !important; left: 0 !important; bottom: 0 !important; right: 0 !important;
        pointer-events: none !important;
        z-index: 2000 !important;
    }

    body::before {
        background: linear-gradient(rgba(20, 20, 100, 0.1) 50%, rgba(0, 0, 0, 0) 50%) !important;
        background-size: 100% 3px !important;
        opacity: 0.3 !important;
    }

    body::after {
        background-image: 
            radial-gradient(2px 2px at 50px 100px, rgba(196, 246, 255, 0.8) 100%, transparent),
            radial-gradient(2px 2px at 150px 200px, rgba(196, 246, 255, 0.8) 100%, transparent),
            radial-gradient(3px 3px at 250px 50px, rgba(196, 246, 255, 0.9) 100%, transparent),
            radial-gradient(2px 2px at 350px 150px, rgba(196, 246, 255, 0.8) 100%, transparent),
            radial-gradient(2px 2px at 450px 250px, rgba(196, 246, 255, 0.8) 100%, transparent) !important;
        background-size: 500px 500px !important;
        animation: snowFall 18s linear infinite !important;
        opacity: 0.6 !important;
    }

    @keyframes snowFall {
        0% { background-position: 0 0; }
        100% { background-position: 500px 1000px; }
    }

    #q, button, p, i, b, .count, a, .logout-btn, nav, nav .links a {
        color: #C4F6FF !important;
    }

    #q, button {
        background-color: black !important;
        font-family: inherit !important;
    }

    a, span, p, div, td, th { 
        text-decoration: none !important; 
    }

    main, .heading, .url-info, td, nav, nav .links, nav .top, .inner, .profile-info {
        background-color: black !important;
        color: #C4F6FF !important;
    }

    .details-table, td {
        border-collapse: collapse !important;
    }

    .icon { display: none !important; }

    img {
        filter: sepia(100%) hue-rotate(179deg) saturate(1.99) !important;
    }

    *, *:before, *:after {
        transition: none !important;
        animation-play-state: paused !important;
    }

    * {
        cursor: url(https://cur.cursors-4u.net/others/oth-1/oth3.png), auto !important;
    }

    .profile-edit-stamp {
        background-image: none !important;
        color: #C4F6FF !important;
        background-color: black !important;
    }

    footer, #footer, .footer, .footer-container {
        background-color: black !important;
        color: #C4F6FF !important;
    }

    footer a, #footer a, .footer a {
        color: #C4F6FF !important; 
    }
}
